INSERT INTO spot (id, district_id, era_id, name, category, era_detail, year_label, address, latitude, longitude, coord_status, story_short, hidden_fact, kto_content_id, accessibility_note, verify_note, review_status) VALUES
    ('SDM01', 'SDM', 'MODERN', '강경대 민주광장(추모 동판)', '추모공간', '현대', '1991', '서울 서대문구 명지대학교 서울캠퍼스 학생회관 앞', 37.5809, 126.9231, 'APPROX', '1991년 시위 중 숨진 명지대 경제학과 학생 강경대를 추모하는 교내 공간.', '1992년 만든 추모 동판은 원래 사건 현장(정문 쪽)에 있었는데, MCC관 공사로 학생회관 앞으로 옮겨지며 광장이 됐다.', NULL, '학생회관 앞 광장 — 진입 동선 현장 확인 필요', '출처가 위키 성격이므로 추모사업회 자료로 교차 확인', 'DRAFT'),
    ('SDM02', 'SDM', 'MODERN', '강경대 열사 거리·표지석(사건 현장)', '표지석', '현대', '1991', '서울 서대문구 명지대학교 서울캠퍼스 정문 앞(MCC관 앞)', 37.58, 126.9238, 'APPROX', '1991년 4월 26일 강경대가 쓰러진 정문 앞 거리. 이 사건을 계기로 전국적인 추모 집회가 이어졌다.', '학교 앞 길이 ''강경대 거리''로 이름 붙어 있다. 기념상(동상)의 상설 설치를 두고 학교와 유족 측 입장이 갈렸다.', NULL, '보도 위치 — 비교적 평탄할 것으로 보이나 현장 확인 필요', '동상 상설 여부는 시점마다 달라짐 — 시연 전 확인', 'DRAFT'),
    ('SDM03', 'SDM', 'OPENING_COLONIAL', '국립대한민국임시정부기념관', '기념관', '일제강점기', NULL, '서울 서대문구 서대문독립공원 인근', NULL, NULL, 'MISSING', '대한민국 임시정부의 역사를 다루는 국립 기념관.', '서대문형무소역사관에서 언덕길을 조금 오르면 닿는다.', NULL, '언덕 — 경사 확인', '주소 확인', 'DRAFT'),
    ('SDM04', 'SDM', 'OPENING_COLONIAL', '독립관', '건축', '대한제국~현대', '1996 복원', '서울 서대문구 통일로 247 서대문독립공원', NULL, NULL, 'MISSING', '조선시대 중국 사신을 맞던 모화관 자리에 복원한 건물로, 순국선열 위패를 모신다.', '안에 순국선열 위패 2,327위가 봉안돼 있다.', NULL, '공원 내 — 평지', NULL, 'DRAFT'),
    ('SDM05', 'SDM', 'OPENING_COLONIAL', '독립문·영은문 주초', '근대건축', '대한제국', '1897', '서울 서대문구 통일로 247 서대문독립공원', 37.5725, 126.9595, 'PROVIDED', '청 사신을 맞던 영은문을 헐고 그 자리에 세운 문. 서재필이 발의하고 독립협회가 건립했다.', '독립문 바로 앞 두 개의 돌기둥이 헐린 영은문의 주춧돌이다. 홍제원 → 영은문으로 이어지던 사신의 길과 연결해서 설명할 수 있다.', NULL, '공원 내 평지 — 접근 쉬움(TourAPI 무장애 정보로 확인)', '2026년 초 보수공사 중이라는 보도 있음 — 시연 시점 확인', 'DRAFT'),
    ('SDM06', 'SDM', 'JOSEON', '모래내·사천교(지명 유래)', '지명', '조선~현대', NULL, '서울 서대문구 남가좌동 모래내시장·홍제천 사천교 일대', 37.5745, 126.919, 'APPROX', '''모래내''는 홍제천의 옛 이름에서 온 지명. 근처 다리 ''사천교(沙川橋)''에 그 이름이 남아 있다.', '''가좌''는 가재가 많은 마을 ''가재울''에서 왔다는 설이 있다. 모래내시장은 한때 서울 4대 시장으로 불렸다.', NULL, '시장 골목·하천변 — 단차 현장 확인 필요', '''가재울'' 유래는 ''가장자리'' 뜻이라는 반론도 있으니 ''설''로 표기', 'DRAFT'),
    ('SDM07', 'SDM', 'JOSEON', '무악산 동봉수대 터(안산 봉수대)', '유적터', '조선 전기', '1438 / 1994 복원', '서울 서대문구 봉원동 산1 안산 정상', 37.5745, 126.9478, 'APPROX', '조선시대 횃불과 연기로 급보를 전하던 봉수대. 평안도에서 온 신호를 남산으로 넘기는 중계 지점이었다.', '터만 남아 있던 것을 1994년 서울 정도 600년 기념사업으로 복원했다. 안산 정상에는 원래 동·서 두 개의 봉수대가 있었다.', '126531', '관광공사 데이터: 주차 불가, 유모차 대여 불가. 정상부라 휠체어 접근 어려움 — 배리어프리 코스에서는 대체 지점 필요', '배리어프리 필터 ''제외'' 시연용 사례로 활용 가능', 'DRAFT'),
    ('SDM08', 'SDM', 'OPENING_COLONIAL', '봉원사', '사찰', '신라 창건/조선 후기 이전', '889(창건)/1748(이전)', '서울 서대문구 봉원사길 120', 37.5686, 126.9445, 'APPROX', '원래 지금의 연세대 자리에 있다가 1748년 안산 자락으로 옮겨온 절. 영조가 현판을 써주며 ''새절''로 불렸다.', '갑신정변 주역 김옥균·박영효 등의 정신적 스승인 이동인 스님이 머문 곳으로, ''갑신정변의 요람''이라 불린다.', '126503', '관광공사 데이터: 화장실 있음, 주차 가능. 산자락 경사 현장 확인', 'TourAPI 무장애 정보 조회로 보강', 'DRAFT'),
    ('SDM09', 'SDM', 'OPENING_COLONIAL', '서대문형무소역사관', '역사관', '일제강점기~현대', '1908~1987', '서울 서대문구 통일로 251', 37.57460851, 126.9556118, 'PROVIDED', '1908년 ''경성감옥''으로 문을 연 감옥. 독립운동가에 이어 해방 뒤에는 민주화운동가들도 갇혔다.', '1987년까지 80년 동안 실제 감옥으로 쓰였다. 강경대·이한열 이야기와 ''민주화운동'' 테마로 이어진다.', NULL, 'TourAPI 무장애 정보 조회 대상(대표 관광지라 데이터 있을 가능성 높음)', '유료 입장 — 요금은 시연 시점에 확인', 'DRAFT'),
    ('SDM10', 'SDM', 'JOSEON', '양호 거사비', '비석', '조선 후기', '1598(원비)/1835(재건)', '서울 서대문구 거북골로 34 명지대학교 서울캠퍼스 교정', 37.5806, 126.9234, 'APPROX', '정유재란 때 조선에 온 명나라 장수 양호를 기리는 송덕비. 형개를 모신 사당 선무사와 함께 세워졌다.', '지금 비석은 1835년 화재로 훼손된 뒤 옛 비문을 다시 새겨 세운 것. 원래 자리가 아닌 대학 캠퍼스에 서 있다.', NULL, '캠퍼스 내 경사로·계단 여부 현장 확인 필요', '교내 정확한 위치 현장 확인 후 좌표 갱신', 'DRAFT'),
    ('SDM11', 'SDM', 'OPENING_COLONIAL', '연세대 스팀슨관·언더우드관·아펜젤러관', '근대건축', '일제강점기', '1920~1925', '서울 서대문구 연세로 50 연세대학교', 37.5655, 126.9387, 'APPROX', '선교사들이 세운 연희전문학교의 초기 석조 건물들. 1981년 사적으로 지정됐다.', '세 건물 모두 기부자 이름을 땄다. 하나의 마스터플랜으로 함께 설계돼 고딕 양식을 공유한다.', NULL, '캠퍼스 내부 경사 있음 — 현장 확인', '세 건물을 핀 하나로 묶음 — 필요하면 분리', 'DRAFT'),
    ('SDM12', 'SDM', 'JOSEON', '연희궁 터·서잠실 터 표석', '표석', '조선 전기', '1420(세종 중건)', '서울 서대문구 연세로 50 연세대학교 정문 안쪽', 37.5606, 126.9369, 'APPROX', '조선 초 왕실의 이궁 연희궁이 있던 자리. 뒤에 왕실 뽕나무밭(서잠실)으로 쓰였다.', '''연희동''과 ''연세(연희+세브란스)''라는 이름이 모두 이 궁에서 왔다.', NULL, '연세대 정문 인근 평지 — 비교적 접근 쉬움(현장 확인)', '표석 정확한 위치 스마트서울맵 ''역사문화표석''에서 확인', 'DRAFT'),
    ('SDM13', 'SDM', 'MODERN', '이한열 열사 피격 현장 동판', '추모 동판', '현대', '1987', '서울 서대문구 연세대학교 정문 왼쪽 기둥 앞 바닥', 37.5598, 126.937, 'APPROX', '1987년 6월 9일 연세대 학생 이한열이 최루탄에 맞아 쓰러진 자리. 6월 민주항쟁의 도화선이 됐다.', '강경대(1991, 명지대)와 이한열(1987, 연세대) — 4년 차이로 이웃한 두 대학 정문 앞에서 일어난 사건을 한 코스로 이을 수 있다.', NULL, '정문 앞 보도 바닥 동판 — 평지', '동판은 2016년 설치', 'DRAFT'),
    ('SDM14', 'SDM', 'JOSEON', '홍제원 터 표석', '표석', '조선', NULL, '서울 서대문구 통일로 416 (새마을금고 홍제2동지점 앞 보도)', 37.5885, 126.9443, 'APPROX', '중국 사신이 한양에 들어가기 전 머물던 국립 숙소 홍제원이 있던 자리. ''홍제동'' 이름의 유래.', '화려한 유적 대신 보도 위 표석 하나만 남아 있어 ''알고 봐야 보이는'' 장소다.', NULL, '큰길 보도 — 평지', '표석 위치 스마트서울맵에서 확인', 'DRAFT'),
    ('SDM15', 'SDM', 'OPENING_COLONIAL', '서대문독립공원', '역사공원', NULL, NULL, '서울 서대문구 통일로 251 일대', 37.5735, 126.9568, 'PROVIDED', '형무소역사관·독립문과 인접한 공원 권역', NULL, NULL, 'TourAPI 무장애 정보 조회 대상', '엑셀 목록에서 추가 — 설명·출처 보강 필요', 'NEEDS_SOURCE'),
    ('MPO01', 'MPO', 'JOSEON', '광흥창 터', '관청 터', '조선', NULL, '서울 마포구 창전동', NULL, NULL, 'MISSING', '관리 녹봉을 보관하던 창고 광흥창 자리.', '지하철 6호선 ''광흥창역'' 이름이 여기서 왔다.', NULL, '현장 확인 필요', NULL, 'DRAFT'),
    ('MPO02', 'MPO', 'OPENING_COLONIAL', '당인리 발전소(마포새빛문화숲)', '발전소', '일제강점기', '1930', '서울 마포구 당인동', NULL, NULL, 'MISSING', '1930년 1호기를 준공한 우리나라 최초의 화력발전소.', '2018년 발전소가 지하로 들어가고 지상은 공원이 됐다.', NULL, '공원 — 확인', NULL, 'DRAFT'),
    ('MPO03', 'MPO', 'JOSEON', '마포·서강·양화 나루', '나루', '조선', NULL, '서울 마포구 한강변', NULL, NULL, 'MISSING', '옛 한강의 16개 포구 가운데 마포 지역에만 세 곳이 있었다.', '새우젓 독이 오가던 상업 포구였다.', NULL, '강변 — 확인', NULL, 'DRAFT'),
    ('MPO04', 'MPO', 'JOSEON', '망원정 터', '정자', '조선 전기', '1424 / 1989 복원', '서울 마포구 동교로8안길 23', 37.5476, 126.9038, 'APPROX', '세종의 형 효령대군이 지은 한강변 정자. 외국 사신을 위한 연회 장소로도 쓰였다.', '세종이 찾았을 때 가뭄 끝에 비가 내려 ''희우정''이 됐다가 뒤에 ''망원정''이 됐다. 바깥과 안쪽에 두 현판이 함께 걸려 있고, ''망원동''이 여기서 이름을 얻었다.', '127307', '관광공사 데이터: 주차 가능. 진입로는 2014년 정비', '학교에서 약 4km — 확장권', 'DRAFT'),
    ('MPO05', 'MPO', 'MODERN', '밤섬', '섬', '현대', '1968', '서울 마포구 한강 밤섬', NULL, NULL, 'MISSING', '한강 한가운데 섬.', '여의도 개발 때 섬이 폭파되며 주민 60여 세대가 창전동으로 이주해야 했다.', NULL, '조망만 가능', NULL, 'DRAFT'),
    ('MPO06', 'MPO', 'JOSEON', '양화나루 터', '나루 터', '조선', NULL, '서울 마포구 합정동 한강변', NULL, NULL, 'MISSING', '한강·송파와 함께 한강 3대 나루였던 양화나루.', NULL, NULL, '강변 — 확인', NULL, 'DRAFT'),
    ('MPO07', 'MPO', 'OPENING_COLONIAL', '양화진 외국인선교사묘원', '묘원', '근대', '1890', '서울 마포구 합정동 144', 37.5455, 126.9118, 'APPROX', '근대 교육·언론·종교에 공헌한 외국인들이 잠든 묘원.', '대한매일신보를 창간한 베델도 이곳에 안장돼 있다.', NULL, '현장 확인 필요', NULL, 'DRAFT'),
    ('MPO08', 'MPO', 'MODERN', '이한열기념관', '기념관', '현대', NULL, '서울 마포구 노고산동', NULL, NULL, 'MISSING', '이한열 열사의 유품과 6월항쟁을 기록한 기념관.', '연세대 정문 앞 피격 현장 동판과 함께 묶을 수 있다.', NULL, '현장 확인 필요', '주소 확인', 'DRAFT'),
    ('MPO09', 'MPO', 'OPENING_COLONIAL', '절두산 순교성지', '순교지', '조선 말', '1866', '서울 마포구 토정로 6', 37.548, 126.9124, 'APPROX', '병인박해 때 많은 천주교인이 처형된 곳.', '원래 이름은 누에 머리를 닮은 ''잠두봉''. 흥선대원군의 척화비도 있다.', NULL, '강변 언덕 — 확인', NULL, 'DRAFT'),
    ('EPY01', 'EPY', 'JOSEON', '금성당', '신당', '조선', NULL, '서울 은평구 진관동', NULL, NULL, 'MISSING', '세종의 여섯째 아들 금성대군을 신으로 모신 신당.', '서울에 세 곳 있던 금성당 중 유일하게 남았다. 은평뉴타운 개발 때 철거될 뻔했다.', NULL, '현장 확인 필요', NULL, 'DRAFT'),
    ('EPY02', 'EPY', 'JOSEON', '북한산성', '산성', '조선 후기', NULL, '서울 은평구 등 북한산 일대', NULL, NULL, 'MISSING', '한양 방어용 산성. 성곽 길이 11.6km.', '한양도성·탕춘대성과 묶어 유네스코 세계유산 등재를 추진 중이다.', NULL, '산지 — 접근 어려움', NULL, 'DRAFT'),
    ('EPY03', 'EPY', 'MODERN', '셋이서문학관', '문학관', '현대', NULL, '서울 은평구 진관동 은평한옥마을', NULL, NULL, 'MISSING', '천상병·이외수·중광 세 사람의 삶과 작품을 전시.', NULL, NULL, '현장 확인 필요', NULL, 'DRAFT'),
    ('EPY04', 'EPY', 'JOSEON', '수국사', '사찰', '조선 전기', '1459', '서울 은평구 서오릉로23길 8-5', NULL, NULL, 'MISSING', '세조가 세운 왕실 원찰.', '법당 안팎을 금으로 입힌 ''황금법당''으로 유명하다.', NULL, '현장 확인 필요', NULL, 'DRAFT'),
    ('EPY05', 'EPY', 'JOSEON', '숙용심씨 묘표', '묘표', '조선', NULL, '서울 은평구 진관동 북한산 둘레길(마실길)', NULL, NULL, 'MISSING', '북한산 둘레길 마실길에서 만나는 조선 왕실 후궁의 묘표.', NULL, NULL, '둘레길 — 확인', NULL, 'DRAFT'),
    ('EPY06', 'EPY', 'JOSEON', '은평역사한옥박물관', '박물관', '현대', '2014', '서울 은평구 진관동 은평한옥마을', NULL, NULL, 'MISSING', '은평의 역사와 한옥을 전시하는 박물관.', '입구 바닥에 대동여지도 원본을 크게 재현해 두었다.', NULL, '신축 — 접근성 양호 예상', NULL, 'DRAFT'),
    ('EPY07', 'EPY', 'OPENING_COLONIAL', '진관사', '사찰', '고려~', NULL, '서울 은평구 진관길 73', NULL, NULL, 'MISSING', '서울 근교 4대 명찰로 꼽히던 절.', '2009년 칠성각 해체·복원 중 벽 속에서 1919년 태극기와 독립신문이 발견됐다.', NULL, '산사 — 경사 일부', NULL, 'DRAFT'),
    ('EPY08', 'EPY', 'OPENING_COLONIAL', '진관사 태극기 비', '비석', '일제강점기', NULL, '서울 은평구 진관사 오르는 길', NULL, NULL, 'MISSING', '진관사 태극기와 백초월 스님을 기리는 석비.', '사찰에서 발견된 유일한 일제강점기 태극기로, 2021년 보물이 됐다.', NULL, '길가 — 평지', NULL, 'DRAFT'),
    ('JNG01', 'JNG', 'JOSEON', '가회동 성당(북촌 천주교 첫 미사)', '성당', '조선 후기', '1795', '서울 종로구 북촌로 57', 37.5824, 126.9852, 'APPROX', '1795년 조선에 들어온 첫 사제 주문모 신부가 북촌 최인길의 집에서 첫 미사를 열었다.', '북촌 한옥마을이 한국 천주교 첫 미사의 무대였다.', NULL, '성당 출입 동선 확인', '첫 미사 장소(최인길 집)의 정확한 위치는 별도 확인', 'DRAFT'),
    ('JNG02', 'JNG', 'JOSEON', '김정희 선생 집터 표석', '표석', '조선 후기', NULL, '서울 종로구 적선동 적선현대빌딩 앞', NULL, NULL, 'MISSING', '추사 김정희가 살던 집터를 알리는 표석.', '원래 통의동에 잘못 세워졌다가 사료 확인 후 적선동 원위치로 옮겨졌다.', NULL, '보도 위 — 평지', '이설 후 현 위치 확인', 'DRAFT'),
    ('JNG03', 'JNG', 'OPENING_COLONIAL', '박규수 집터', '집터', '조선 말', NULL, '서울 종로구 재동 헌법재판소 내', 37.5795, 126.9855, 'APPROX', '개화사상의 선구자로 꼽히는 구한말 우의정 박규수가 살던 자리.', '지금은 헌법재판소 부지 안에 있다.', NULL, '기관 내부 — 출입 가능 여부 확인', NULL, 'DRAFT'),
    ('JNG04', 'JNG', 'JOSEON', '보신각', '누각', '조선', NULL, '서울 종로구 종로 54', 37.5699, 126.9837, 'APPROX', '보신각종을 걸어 둔 누각. 도성의 시간을 알리던 종이 있던 곳.', '매년 12월 31일 자정 33번 타종하는 제야의 종 행사가 열린다.', NULL, '대로변 — 평지', NULL, 'DRAFT'),
    ('JNG05', 'JNG', 'MODERN', '서울 중심점 표지석', '표지석', '현대', NULL, '서울 종로구 인사동5길 25 하나로빌딩 1층 로비', 37.5727, 126.9857, 'APPROX', '서울의 지리적 중심을 표시한 표지석.', '거리가 아니라 건물 로비 안에 있어 알고 가야 찾을 수 있다.', NULL, '건물 내부 — 출입 시간 확인', NULL, 'DRAFT'),
    ('JNG06', 'JNG', 'JOSEON', '안동별궁 터 표석', '표석', '조선 후기', NULL, '서울 종로구 안국동 옛 풍문여고 자리', 37.5763, 126.9842, 'APPROX', '조선 후기 왕실 별궁이 있던 자리. 1998년 학교 안에 표석이 세워졌다.', '서울시가 표석 문안을 다시 쓰기 위해 원 사료를 전면 조사한 대표 사례로 꼽혔다.', NULL, '현장 확인 필요', '옛 풍문여고 부지는 현재 서울공예박물관 — 표석 현 위치 확인', 'DRAFT'),
    ('JNG07', 'JNG', 'JOSEON', '육의전 터 표석', '표석', '조선', NULL, '서울 종로구 종로타워 앞 쉼터(종각역 3번 출구)', 37.5704, 126.983, 'APPROX', '조선 시전 상인 중 가장 큰 여섯 상점(육의전)이 있던 종로 상권의 흔적.', '표석 앞에 다른 단체가 세운 큰 돌이 있어 정작 표석이 잘 안 보인다.', NULL, '쉼터 — 평지', NULL, 'DRAFT'),
    ('JNG08', 'JNG', 'OPENING_COLONIAL', '윤보선 가옥', '가옥', '근대', NULL, '서울 종로구 안국동', 37.5786, 126.9843, 'APPROX', '윤보선 전 대통령이 살던 집으로 사적으로 보호되고 있다.', '박규수 집터(헌법재판소) 바로 뒤에 있어 두 곳을 한 번에 볼 수 있다.', NULL, '내부 비공개 — 외부 관람', NULL, 'DRAFT'),
    ('JNG09', 'JNG', 'JOSEON', '의금부 터 표석', '표석', '조선', NULL, '서울 종로구 종각역 1번 출구 앞', 37.5702, 126.9826, 'APPROX', '조선시대 왕명을 받아 중죄인을 심문하던 관청 의금부가 있던 자리.', '지하철 출구 바로 앞, 번화가 한복판이 옛 최고 사법기관 자리였다.', NULL, '보도 위 — 평지', NULL, 'DRAFT'),
    ('JNG10', 'JNG', 'JOSEON', '조광조 집터 표석', '표석', '조선 전기', NULL, '서울 종로구 낙원상가 맞은편 도로변', NULL, NULL, 'MISSING', '개혁 정치가 정암 조광조의 집터.', '도봉구 도봉서원(조광조 배향)과 묶어 ''조광조 코스''로 이을 수 있다.', NULL, '보도 위 — 평지', NULL, 'DRAFT'),
