INSERT INTO cross_link (id, title, era_flow, story) VALUES
    ('X1', '사신의 길이 독립의 상징으로', '조선 → 개화기·일제강점기', '조선시대 중국 사신은 홍제원에서 묵고 모화관에서 영접받은 뒤 영은문을 지나 도성에 들어갔다. 1897년 영은문을 헐고 독립문을 세웠고, 모화관 자리는 독립관이 됐다.'),
    ('X2', '연세대 캠퍼스, 한 땅의 네 시대', '조선 → 개화기·일제강점기 → 현대', '신라 말 봉원사가 처음 지어진 자리, 세종이 고쳐 지은 연희궁 터, 1920년대 연희전문의 석조 건물, 1987년 이한열이 쓰러진 정문이 모두 지금의 연세대 캠퍼스에 있다.'),
    ('X3', '명지대 캠퍼스, 정유재란과 1991년', '조선 → 현대', '정유재란 때 명나라 장수 양호를 기린 비(1598년 처음 세움, 1835년 다시 새김)와 1991년 강경대 열사를 기리는 광장·거리가 같은 캠퍼스에 있다.'),
    ('X4', '같은 감옥, 두 시대의 수감자', '개화기·일제강점기 → 현대', '1908년 문을 연 감옥에 일제강점기에는 독립운동가가, 해방 뒤에는 민주화운동가가 갇혔다. 1987년 의왕으로 옮겨간 뒤 1992년 그 자리가 서대문독립공원이 됐다.'),
    ('X5', '김구, 수감자에서 귀국한 지도자로', '개화기·일제강점기 → 현대', '김구는 일제강점기 서대문형무소 12옥사에 갇혔고, 광복 뒤에는 경교장에 머물렀다. 그가 이끈 임시정부의 기념관이 형무소 위 언덕에 있다.'),
    ('X6', '3·1운동이 남긴 세 장소', '개화기·일제강점기 → 현대', '1919년 탑골공원에서 3·1운동이 시작됐다. 탑골공원에 있던 3·1독립선언기념탑은 1992년 서대문독립공원으로 옮겨졌고, 진관사 벽 속에 숨겨졌던 1919년 무렵 태극기는 2009년에야 발견돼 2021년 보물이 됐다.'),
    ('X7', '잠두봉, 명승지에서 순교지로', '조선 → 개화기·일제강점기', '조선 사람들이 경치를 즐기던 양화나루 언덕 잠두봉이 1866년 병인박해 때 처형지가 되어 ''절두산''으로 불리게 됐다. 바로 옆에는 1890년 외국인선교사묘원이 생겼고, 근처에는 효령대군의 망원정이 있다.'),
    ('X8', '단종의 삼촌들, 은평에서 다시 만나다', '조선 → 현대', '단종을 몰아낸 세조가 세운 수국사와, 단종을 지키려다 죽은 금성대군의 신당 금성당이 같은 은평구에 있다. 금성당은 2008년 은평뉴타운 개발 때 철거될 뻔했다가 남았다.');
